/**
 * Unicode decimal-digit support, mirroring what CPython's `int()` accepts.
 *
 * CPython accepts any character in the general category `Nd` as a decimal
 * digit, so `int('٣')`, `int('۳')` and `int('𝟑')` all evaluate to 3, while
 * `int('²')` (category `No`) raises ValueError.
 */

const ND = /^\p{Nd}$/u;

/** True when the code point is a Unicode decimal digit (category Nd). */
export function isDecimalDigit(codePoint) {
  if (codePoint >= 0x30 && codePoint <= 0x39) return true;
  if (codePoint < 0x80 || codePoint > 0x10ffff) return false;
  return ND.test(String.fromCodePoint(codePoint));
}

/**
 * Numeric value 0-9 of a decimal-digit code point, or -1 when it is not one.
 *
 * Unicode guarantees every decimal-digit set occupies a contiguous run of ten
 * code points beginning with the digit zero. Some of those runs sit directly
 * beside each other (the five mathematical alphanumeric sets fill
 * U+1D7CE..U+1D7FF without a gap), so walking back to the first non-digit can
 * overshoot the zero of our own set. Because a maximal run is always a whole
 * number of aligned ten-code-point sets, taking the offset modulo ten
 * recovers the digit value in every case.
 */
export function decimalDigitValue(codePoint) {
  if (codePoint >= 0x30 && codePoint <= 0x39) return codePoint - 0x30;
  if (!isDecimalDigit(codePoint)) return -1;

  let runStart = codePoint;
  while (runStart > 0 && isDecimalDigit(runStart - 1)) runStart--;
  return (codePoint - runStart) % 10;
}

