/**
 * The whitespace CPython's integer parser skips around a numeric literal.
 *
 * The parser uses two different tests depending on the code point: ASCII
 * characters go through a C-style `isspace`, everything else through the
 * Unicode whitespace table. That split is observable — U+001C..U+001F are
 * whitespace for `str.isspace()` yet are rejected by `int()`, while the
 * non-ASCII U+0085 and U+00A0 are both accepted.
 */

const ASCII_SPACE = [0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20];
const NON_ASCII_SPACE = [0x85, 0xa0, 0x1680, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000];

/** True when `int()` would skip this code point as leading/trailing space. */
export function isIntSpace(codePoint) {
  if (codePoint < 0x80) return ASCII_SPACE.includes(codePoint);
  if (codePoint >= 0x2000 && codePoint <= 0x200a) return true;
  return NON_ASCII_SPACE.includes(codePoint);
}

/** Strip leading and trailing `int()`-recognised whitespace from `text`. */
export function stripIntSpace(text) {
  const points = Array.from(text);
  let start = 0;
  let end = points.length;
  while (start < end && isIntSpace(points[start].codePointAt(0))) start++;
  while (end > start && isIntSpace(points[end - 1].codePointAt(0))) end--;
  return points.slice(start, end).join('');
}

