input.content:
/**
 * `int(text)` for base-10 strings, reproducing CPython's accepted grammar:
 *
 *     [space] [ '+' | '-' ] digit ( '_'? digit )* [space]
 *
 * Digits may come from any Unicode decimal-digit set and may be mixed freely.
 * Underscores are only legal between two digits, so '_1', '1_' and '1__0' are
 * all rejected. The result is a BigInt: Python integers are unbounded, and
 * `int('99999999999999999999')` must not lose precision.
 */

import { decimalDigitValue } from './unicode_digits.mjs';
import { stripIntSpace } from './whitespace.mjs';

/** Raised for input `int()` would reject, mirroring Python's ValueError. */
export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

/**
 * Convert `text` to a BigInt using Python's `int()` rules.
 * @throws {PyValueError} when the text is not a valid base-10 integer literal.
 */
export function pyInt(text) {
  const body = stripIntSpace(text);
  const points = Array.from(body);

  let cursor = 0;
  let negative = false;
  if (points[cursor] === '+' || points[cursor] === '-') {
    negative = points[cursor] === '-';
    cursor++;
  }

  let digits = '';
  let previousWasDigit = false;
  for (; cursor < points.length; cursor++) {
    const character = points[cursor];
    if (character === '_') {
      // An underscore needs a digit on both sides.
      if (!previousWasDigit) throw invalidLiteral(text);
      previousWasDigit = false;
      continue;
    }
    const value = decimalDigitValue(character.codePointAt(0));
    if (value < 0) throw invalidLiteral(text);
    digits += String(value);
    previousWasDigit = true;
  }

  if (digits === '' || !previousWasDigit) throw invalidLiteral(text);
  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

function invalidLiteral(text) {
  return new PyValueError(
    `invalid literal for int() with base 10: ${JSON.stringify(text)}`,
  );
}

