/**
 * An insertion-ordered dictionary with Python key semantics.
 *
 * Lookups go through a null-prototype index of hash tokens to slot numbers,
 * which keeps membership tests O(1) while the parallel `keys`/`values` arrays
 * preserve insertion order the way Python dictionaries do.
 */

import { hashToken } from './objects.mjs';

export class PyDict {
  #slots = Object.create(null);
  #keys = [];
  #values = [];

  constructor(entries) {
    if (entries !== undefined) {
      for (const [key, value] of normalizeEntries(entries)) this.set(key, value);
    }
  }

  get size() {
    return this.#keys.length;
  }

  /** `key in dict` */
  has(key) {
    return this.#slots[hashToken(key)] !== undefined;
  }

  /** `dict[key]`, or `fallback` when absent. */
  get(key, fallback = undefined) {
    const slot = this.#slots[hashToken(key)];
    return slot === undefined ? fallback : this.#values[slot];
  }

  /** `dict[key] = value`; an existing key keeps its original position. */
  set(key, value) {
    const token = hashToken(key);
    const slot = this.#slots[token];
    if (slot === undefined) {
      this.#slots[token] = this.#keys.length;
      this.#keys.push(key);
      this.#values.push(value);
    } else {
      this.#values[slot] = value;
    }
    return this;
  }

  /** `del dict[key]`; returns whether the key was present. */
  delete(key) {
    const token = hashToken(key);
    const slot = this.#slots[token];
    if (slot === undefined) return false;

    this.#keys.splice(slot, 1);
    this.#values.splice(slot, 1);
    delete this.#slots[token];
    for (const remaining of Object.keys(this.#slots)) {
      if (this.#slots[remaining] > slot) this.#slots[remaining]--;
    }
    return true;
  }

  clear() {
    this.#slots = Object.create(null);
    this.#keys = [];
    this.#values = [];
  }

  keys() {
    return this.#keys.slice();
  }

  values() {
    return this.#values.slice();
  }

  items() {
    return this.#keys.map((key, index) => [key, this.#values[index]]);
  }

  [Symbol.iterator]() {
    return this.keys()[Symbol.iterator]();
  }
}

/** Accept a PyDict, an array of pairs, or a plain object as initial entries. */
export function normalizeEntries(source) {
  if (source instanceof PyDict) return source.items();
  if (Array.isArray(source)) return source.map(([key, value]) => [key, value]);
  if (source && typeof source === 'object') {
    return Object.keys(source).map((key) => [key, source[key]]);
  }
  throw new TypeError('cannot build a dict from the given value');
}

