/** Exception hierarchy mirroring `bidict`'s own error classes. */

/** Base class for every bidirectional-mapping error. */
export class BidictError extends Error {
  constructor(message) {
    super(message);
    this.name = new.target.name;
  }
}

/** Raised when a key that is already mapped would be overwritten. */
export class KeyDuplicationError extends BidictError {}

/** Raised when a value is already bound to a different key. */
export class ValueDuplicationError extends BidictError {}

/** Raised when a key and a value each collide with a different existing pair. */
export class KeyAndValueDuplicationError extends
  (KeyDuplicationError, ValueDuplicationError) {}

