/**
 * A bidirectional mapping: keys and values are both unique, and `.inv`
 * exposes the reversed view.
 *
 * The forward and inverse directions are two ordered dictionaries kept in
 * step by every mutation. The inverse instance is created once and holds the
 * same two dictionaries with their roles swapped, so `b.inv.inv === b` and
 * updates are visible through either side without any copying.
 */

import { PyDict, normalizeEntries } from '../python/dict.mjs';
import { pyRepr } from '../python/objects.mjs';
import { KeyDuplicationError, ValueDuplicationError, KeyAndValueDuplicationError } from './errors.mjs';

/** Duplication policy for a write, matching bidict's ON_DUP behaviour. */
const RAISE = 'RAISE';
const OVERWRITE = 'OVERWRITE';

export class Bidict {
  #forward;
  #inverse;
  #inv = null;

