/** Control-flow exceptions used by the argument parser. */

/**
 * Python's `SystemExit`. The parser raises this instead of terminating the
 * process so the entry point stays in control and buffered output is flushed
 * normally before Node exits.
 */
export class SystemExit extends Error {
  constructor(code) {
    super(`SystemExit: ${code}`);
    this.name = 'SystemExit';
    this.code = code;
  }
}

/** Raised by a `type` callable to reject a value, like `argparse.ArgumentTypeError`. */
export class ArgumentTypeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentTypeError';
  }
}

