/**
 * Usage and help rendering, reproducing argparse's `HelpFormatter` layout for
 * the option-only parsers this program builds.
 */

const INDENT = '  ';
const MAX_HELP_POSITION = 24;

/** `--key KEY` / `-h` — how an action appears inside the usage line. */
function formatUsagePart(action) {
  const optionString = action.optionStrings[0];
  const text = action.takesValue ? `${optionString} ${action.metavar}` : optionString;
  return action.required ? text : `[${text}]`;
}

/** `-h, --help` / `--key KEY` — the left column of the options list. */
function formatInvocation(action) {
  if (!action.takesValue) return action.optionStrings.join(', ');
  return action.optionStrings.map((option) => `${option} ${action.metavar}`).join(', ');
}

/** The `usage: ...` line, without a trailing newline. */
