 * program relies on: long options with `--opt value` and `--opt=value` forms,
 * unique-prefix abbreviation, required options, per-argument type conversion,
 * `-h/--help`, and argparse's exact error text and exit status.
 */

import { SystemExit, ArgumentTypeError } from './errors.mjs';
import { formatUsage, formatHelp } from './formatter.mjs';
import { pyRepr } from '../python/objects.mjs';
import { writeStdout, writeStderr } from '../io/streams.mjs';

/**
 * argparse's own test for "this looks like a negative number, not a flag".
 * Python's `\d` is Unicode-aware, so `-١` counts as a number here too.
 */
const NEGATIVE_NUMBER = /^-\p{Nd}+$|^-\p{Nd}*\.\p{Nd}+$/u;

export class ArgumentParser {
  #prog;
  #actions = [];
  #optionIndex = Object.create(null);

  constructor({ prog = 'prog', addHelp = true } = {}) {
    this.#prog = prog;
    if (addHelp) {
      this.addArgument(['-h', '--help'], {
        action: 'help',
        help: 'show this help message and exit',
      });
    }
  }

  /**
   * Register an option.
   * @param {string[]|string} optionStrings e.g. `['--key']` or `['-h','--help']`
   * @param {{action?: string, type?: Function, required?: boolean,
   *          help?: string, dest?: string, metavar?: string,
   *          default?: unknown}} options
   */
  addArgument(optionStrings, options = {}) {
    const strings = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
    const isHelp = options.action === 'help';
    const dest =
      options.dest ??
      strings
        .find((option) => option.startsWith('--'))
        .replace(/^--/, '')
        .replace(/-/g, '_');

    const action = {
      optionStrings: strings,
      dest,
      takesValue: !isHelp,
      isHelp,
      type: options.type ?? String,
      required: options.required ?? false,
      help: options.help ?? '',
      metavar: options.metavar ?? dest.toUpperCase(),
      default: options.default ?? null,
    };

    this.#actions.push(action);
    for (const option of strings) this.#optionIndex[option] = action;
    return action;
  }

  get prog() {
    return this.#prog;
  }

  formatUsage() {
    return formatUsage(this.#prog, this.#actions) + '\n';
  }

  formatHelp() {
    return formatHelp(this.#prog, this.#actions);
  }

  printHelp() {
    writeStdout(this.formatHelp());
  }

  /** Print usage plus `prog: error: message` to stderr and exit with status 2. */
  error(message) {
    writeStderr(this.formatUsage());
    writeStderr(`${this.#prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  /** `parser.parse_args()` — like parseKnownArgs but rejects leftover tokens. */
  parseArgs(argv) {
    const { namespace, extras } = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  /** `parser.parse_known_args()` — returns parsed values and unconsumed tokens. */
  parseKnownArgs(argv) {
    const namespace = Object.create(null);
    for (const action of this.#actions) {
      if (!action.isHelp) namespace[action.dest] = action.default;
    }

    const extras = [];
    const seen = Object.create(null);
    let index = 0;
    let afterDoubleDash = false;

    while (index < argv.length) {
      const token = argv[index];

      // Everything from the first `--` onwards is positional. This parser
      // defines no positionals, so those tokens end up unrecognised — and the
      // `--` itself is only removed when a positional consumes it, so it
      // stays behind too.
      if (afterDoubleDash) {
        extras.push(token);
        index++;
        continue;
      }
      if (token === '--') {
        afterDoubleDash = true;
        extras.push(token);
        index++;
        continue;
      }

      const candidate = this.#parseOptional(token);
      if (candidate === null || candidate.action === null) {
        extras.push(token);
        index++;
        continue;
      }

      const { action, optionString } = candidate;
      let explicitArg = candidate.explicitArg;
      index++;

      if (action.isHelp) {
        this.printHelp();
        throw new SystemExit(0);
      }

      if (explicitArg === null) {
        const next = argv[index];
        if (next === undefined || next === '--' || this.#parseOptional(next) !== null) {
          this.error(`argument ${actionName(action)}: expected one argument`);
        }
        explicitArg = next;
        index++;
      }

      namespace[action.dest] = this.#convert(action, optionString, explicitArg);
      seen[action.dest] = true;
    }

    // argparse reports missing required options before unrecognised ones.
    const missing = this.#actions
      .filter((action) => action.required && !seen[action.dest])
      .map(actionName);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return { namespace, extras };
  }

  /** Apply an action's `type` callable, reporting failures argparse-style. */
  #convert(action, optionString, text) {
    try {
      return action.type(text);
    } catch (problem) {
      if (problem instanceof SystemExit) throw problem;
      const typeName = action.type.name || 'value';
      if (problem instanceof ArgumentTypeError) {
        this.error(`argument ${actionName(action)}: ${problem.message}`);
      }
      this.error(
        `argument ${actionName(action)}: invalid ${typeName} value: ${pyRepr(text)}`,
      );
      return undefined;
    }
  }

  /**
   * Classify a token, following argparse's order of checks.
   *
   * Returns `null` when the token is positional, `{action: null, ...}` for an
   * unknown flag, or the matched action otherwise.
   */
  #parseOptional(argString) {
    if (!argString) return null;
    if (argString[0] !== '-') return null;

    const exact = this.#optionIndex[argString];
    if (exact !== undefined) {
      return { action: exact, optionString: argString, explicitArg: null };
    }
    // A bare '-' was meant to be positional.
    if (argString.length === 1) return null;

    const equals = argString.indexOf('=');
    if (equals !== -1) {
      const head = argString.slice(0, equals);
      const headAction = this.#optionIndex[head];
      if (headAction !== undefined) {
        return {
          action: headAction,
          optionString: head,
          explicitArg: argString.slice(equals + 1),
        };
      }
    }

    const matches = this.#optionTuples(argString);
    if (matches.length > 1) {
