    if (matches.length === 1) return matches[0];

    // Negative numbers are values, not flags, unless a flag looks like one.
    if (NEGATIVE_NUMBER.test(argString) && !this.#hasNegativeNumberOptions()) return null;
    // Anything containing a space is a value too.
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, explicitArg: null };
  }

  /** Unique-prefix abbreviation matches for a token. */
  #optionTuples(argString) {
    const matches = [];
    const registered = Object.keys(this.#optionIndex);

    if (argString.startsWith('--')) {
      let prefix = argString;
      let explicitArg = null;
      const equals = argString.indexOf('=');
      if (equals !== -1) {
        prefix = argString.slice(0, equals);
        explicitArg = argString.slice(equals + 1);
      }
      for (const option of registered) {
        if (option.startsWith(prefix)) {
          matches.push({ action: this.#optionIndex[option], optionString: option, explicitArg });
        }
      }
    } else {
      const shortOption = argString.slice(0, 2);
      const shortExplicitArg = argString.slice(2);
      for (const option of registered) {
        if (option === shortOption) {
