            action: this.#optionIndex[option],
            optionString: option,
            explicitArg: shortExplicitArg,
          });
        } else if (option.startsWith(argString)) {
          matches.push({
            action: this.#optionIndex[option],
            optionString: option,
            explicitArg: null,
          });
        }
      }
    }
    return matches;
  }

  #hasNegativeNumberOptions() {
    return Object.keys(this.#optionIndex).some((option) => NEGATIVE_NUMBER.test(option));
  }
