/**
 * Process output and exit handling.
 *
 * Writes go through the standard streams and the program finishes by setting
 * `process.exitCode` rather than calling `process.exit()`, which would risk
 * truncating buffered output when stdout is a pipe.
 */

/** Write text to stdout with no added newline. */
export function writeStdout(text) {
  process.stdout.write(text);
}

/** Write text to stderr with no added newline. */
export function writeStderr(text) {
  process.stderr.write(text);
}

/** The command-line arguments, excluding the node binary and script path. */
export function argv() {
  return process.argv.slice(2);
}

/** Request an exit status without cutting pending writes short. */
export function setExitCode(code) {
  process.exitCode = code;
}

