 *
 * Reads --key and --val, then checks membership in a bidict and its inverse.
 * Run: node test6.mjs --key b --val 3
 */

import { ArgumentParser, SystemExit } from './lib/argparse/index.mjs';
import { bidict } from './lib/bidict/index.mjs';
import { pyInt } from './lib/python/int.mjs';
import { pyStr } from './lib/python/objects.mjs';
import { argv, writeStdout, setExitCode } from './lib/io/streams.mjs';

/** `type=str`: argparse hands the raw text straight through. */
function str(text) {
  return text;
}

/** `type=int`. The function name is what argparse prints on a bad value. */
function int(text) {
  return pyInt(text);
}

function main(args) {
  const parser = new ArgumentParser({ prog: 'test6_executable' });
  parser.addArgument(['--key'], { type: str, required: true });
  parser.addArgument(['--val'], { type: int, required: true });
  const parsed = parser.parseArgs(args);

  // 检查键和值的存在性
  const b = bidict({ a: 1, b: 2, c: 3 });
  const result1 = b.has(parsed.key);
  const result2 = b.inv.has(parsed.val);
  writeStdout(pyStr(result1) + '\n');
  writeStdout(pyStr(result2) + '\n');
}

try {
  main(argv());
} catch (problem) {
  if (!(problem instanceof SystemExit)) throw problem;
  setExitCode(problem.code);
