/**
 * The pieces of Python's object protocol this program observes: how values
 * print, how they repr, and how they behave as dictionary keys.
 */

/** `print()`-style text for a value (`True`/`False` for booleans). */
export function pyStr(value) {
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (typeof value === 'bigint') return value.toString();
  if (value === null || value === undefined) return 'None';
  return String(value);
}

const SHORT_ESCAPES = { '\\': '\\\\', '\n': '\\n', '\r': '\\r', '\t': '\\t' };

/**
 * `repr()` of a string. Python prefers single quotes but switches to double
 * quotes when the text contains a single quote and no double quote, which is
 * why argparse reports `invalid int value: "a'b"`.
 */
export function pyRepr(value) {
  if (typeof value !== 'string') return pyStr(value);

  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";
  let body = '';
  for (const character of value) {
    if (character === quote) {
      body += '\\' + character;
    } else if (SHORT_ESCAPES[character] !== undefined) {
      body += SHORT_ESCAPES[character];
    } else {
      const codePoint = character.codePointAt(0);
      const isControl =
        codePoint < 0x20 || codePoint === 0x7f || (codePoint >= 0x80 && codePoint <= 0x9f);
      body += isControl
        ? '\\x' + codePoint.toString(16).padStart(2, '0')
        : character;
    }
  }
  return quote + body + quote;
}

/**
 * Canonical lookup token for a hashable value.
 *
 * The prefix keeps types that never compare equal in separate namespaces, so
 * the string 'a' cannot collide with anything numeric. Integers all normalise
 * to one decimal form because Python treats `1`, `1.0` and `True` as the same
 * key.
 */
export function hashToken(key) {
  switch (typeof key) {
    case 'string':
      return 's:' + key;
    case 'bigint':
      return 'i:' + key.toString();
    case 'boolean':
      return 'i:' + (key ? '1' : '0');
    case 'number':
      if (Number.isInteger(key)) return 'i:' + BigInt(key).toString();
      return 'f:' + String(key);
    case 'undefined':
      return 'n:';
    case 'object':
      if (key === null) return 'n:';
      break;
    default:
      break;
  }
  throw new TypeError(`unhashable type: ${typeof key}`);
}

