/**
 * Differential test: run the reference executable and the Node port over the
 * same argument vectors and compare stdout, stderr and exit status exactly.
 *
 * Usage: node compare.mjs
 */

import { execFileSync } from 'node:child_process';

const REFERENCE = '/workspace/dataset/test6_executable';
const PORT = '/output/test6.mjs';

function run(command, args) {
  try {
    const stdout = execFileSync(command, args, {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    return { code: 0, stdout, stderr: '' };
  } catch (error) {
    return {
      code: error.status === null ? `signal:${error.signal}` : error.status,
      stdout: error.stdout ?? '',
      stderr: error.stderr ?? '',
    };
  }
}

const ch = (cp) => String.fromCodePoint(cp);

const cases = [
  // Sample cases from the source file.
  ['--key', 'b', '--val', '3'],
  ['--key', 'a', '--val', '3'],
  ['--key', 'c', '--val', '1'],
  // Every key/value combination, present and absent.
  ...['a', 'b', 'c', 'z', '', '1', 'A', 'á', 'ab'].flatMap((key) =>
    ['1', '2', '3', '0', '4', '-1', '99'].map((val) => ['--key', key, '--val', val]),
  ),
  // Missing / required arguments.
  [],
  ['--key', 'a'],
  ['--val', '1'],
  ['--key'],
  ['--val'],
  ['--val', 'abc'],
  // Help.
  ['--help'],
  ['-h'],
  ['--key', 'a', '-h'],
  ['-h', '--bogus'],
  // `--opt=value` and abbreviation.
  ['--key=a', '--val=2'],
  ['--k', 'a', '--v', '1'],
  ['--ke', 'a', '--va', '2'],
  ['--k=a', '--v=2'],
  ['--key=-a', '--val', '1'],
  ['--key=--val', '--val', '1'],
  ['--key=', '--val', '1'],
  // int() acceptance and rejection.
  ...[
    '1_0', '1_000', '_1', '1_', '1__0', '+2', '-0', '003', '0x2', '1.5', '3.', '.3',
    '', ' ', '  2  ', '99999999999999999999', '-3', '١_0', '١3',
  ].map((val) => ['--key', 'a', '--val', val]),
  // Unicode digits (Nd) versus non-decimal numerics.
  ...['٣', '٢', '۳', '１', '１２', '-１', '١٠', '𝟑', '²', '½', '〇', '๓'].map((val) => [
    '--key', 'a', '--val', val,
  ]),
  // Whitespace handling around the literal.
  ...[0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1f, 0x20, 0x85, 0xa0, 0x1680, 0x2000, 0x2009,
      0x2028, 0x2029, 0x202f, 0x205f, 0x3000, 0x200b, 0x180e, 0x2060, 0xfeff].map((cp) => [
    '--key', 'a', '--val', ch(cp) + '3' + ch(cp),
  ]),
  // Values that look like flags.
  ['--key', '-a', '--val', '1'],
  ['--key', '--val', '1'],
  ['--val', '3', '--key'],
  ['--key', 'a', '--val', '-_1'],
  ['--key', 'a', '--val', '--1'],
  ['--key', 'a', '--val', ' -3'],
  ['--key', 'a', '--val', '-١'],
  ['--key', 'a b', '--val', '1'],
  ['--key', '-', '--val', '1'],
  // Unrecognised tokens.
  ['--key', 'a', '--val', '1', '--bogus', '2'],
  ['--key', 'a', '--val', '1', '--bogus=2'],
  ['--key', 'a', '--val', '1', '-x'],
  ['--key', 'a', '--val', '1', '-3'],
  ['--key', 'a', '--val', '1', '-'],
  ['--key', 'a', '--val', '1', 'foo', 'bar'],
  ['foo', '--key', 'a', '--val', '1'],
  // `--` separator.
  ['--key', 'a', '--val', '1', '--'],
  ['--key', 'a', '--val', '1', '--', '--'],
  ['--key', 'a', '--', '--val', '1'],
  ['--', '--key', 'a', '--val', '1'],
  ['--key', '--', 'x', '--val', '1'],
  // Repeated options: the last one wins.
  ['--key', 'a', '--key', 'z', '--val', '1'],
  ['--key', 'a', '--val', '1', '--val', '99'],
  // repr() quoting in error text.
  ['--key', 'a', '--val', "a'b"],
  ['--key', 'a', '--val', 'a"b'],
  ['--key', 'a', '--val', 'a\'b"c'],
  ['--key', 'a', '--val', 'a\nb'],
  ['--key', 'a', '--val', 'a\\b'],
];

let failures = 0;
for (const args of cases) {
  const expected = run(REFERENCE, args);
  const actual = run('node', [PORT, ...args]);
  const same =
    expected.stdout === actual.stdout &&
    expected.stderr === actual.stderr &&
    expected.code === actual.code;
  if (!same) {
    failures++;
    console.log('MISMATCH  args=' + JSON.stringify(args));
    console.log('  expected: ' + JSON.stringify(expected));
    console.log('  actual:   ' + JSON.stringify(actual));
  }
}

console.log(`\n${cases.length - failures}/${cases.length} cases match`);
if (failures > 0) process.exitCode = 1;

