/**
 * Self-test for the library modules — the parts the entry script does not
 * exercise on its own (inverse views, duplication policy, int edge cases).
 *
 * Usage: node selftest.mjs
 */

import { bidict, ValueDuplicationError, KeyDuplicationError } from './lib/bidict/index.mjs';
import { pyInt, PyValueError } from './lib/python/int.mjs';
import { pyRepr, pyStr } from './lib/python/objects.mjs';
import { PyDict } from './lib/python/dict.mjs';

let failures = 0;

function check(label, actual, expected) {
  const ok = Object.is(actual, expected);
  if (!ok) {
    failures++;
    console.log(`FAIL ${label}: got ${String(actual)}, want ${String(expected)}`);
  }
}

function throws(label, fn, ErrorClass) {
  try {
    fn();
  } catch (problem) {
    if (problem instanceof ErrorClass) return;
    failures++;
    console.log(`FAIL ${label}: raised ${problem.name}, want ${ErrorClass.name}`);
    return;
  }
  failures++;
  console.log(`FAIL ${label}: nothing raised, want ${ErrorClass.name}`);
}

// --- bidict basics -------------------------------------------------------
const b = bidict({ a: 1, b: 2, c: 3 });
check('size', b.size, 3);
check('has present', b.has('a'), true);
check('has absent', b.has('z'), false);
check('get', b.get('b'), 2);
check('inv has value', b.inv.has(3), true);
check('inv has absent', b.inv.has(9), false);
check('inv maps back', b.inv.get(3), 'c');
check('inv.inv identity', b.inv.inv, b);
check('inv is cached', b.inv, b.inv);
check('repr', b.toString(), "bidict({'a': 1, 'b': 2, 'c': 3})");

// Integers compare across numeric representations, as in Python.
check('bigint lookup', b.inv.has(3n), true);
check('float-int lookup', b.inv.has(3.0), true);
check('true equals one', b.inv.has(true), true);
check('non-integer float', b.inv.has(3.5), false);
check('string is not int', b.has('1'), false);

// --- duplication policy --------------------------------------------------
throws('duplicate value at construction', () => bidict({ a: 1, b: 1 }), ValueDuplicationError);
throws('put onto existing key', () => bidict({ a: 1 }).put('a', 9), KeyDuplicationError);
throws('put onto existing value', () => bidict({ a: 1 }).put('z', 1), ValueDuplicationError);
check('re-putting the same pair is a no-op', bidict({ a: 1 }).put('a', 1).size, 1);

// --- mutation propagates through both views ------------------------------
const m = bidict({ a: 1 });
m.put('b', 2);
check('put updates inverse', m.inv.get(2), 'b');
m.inv.put(3, 'c');
check('put via inverse updates forward', m.get('c'), 3);
m.forceput('a', 2);
check('forceput rebinds key', m.get('a'), 2);
check('forceput evicts old key', m.has('b'), false);
m.delete('a');
check('delete clears forward', m.has('a'), false);
check('delete clears inverse', m.inv.has(2), false);

// --- ordered dict --------------------------------------------------------
const d = new PyDict([['x', 1], ['y', 2], ['z', 3]]);
check('dict order', d.keys().join(','), 'x,y,z');
d.delete('y');
check('dict order after delete', d.keys().join(','), 'x,z');
check('dict lookup after delete', d.get('z'), 3);
d.set('x', 9);
check('overwrite keeps position', d.keys().join(','), 'x,z');

// --- int() ---------------------------------------------------------------
check('plain', pyInt('42'), 42n);
check('sign', pyInt('-7'), -7n);
check('underscores', pyInt('1_000'), 1000n);
check('whitespace', pyInt('  12  '), 12n);
check('unicode digits', pyInt('٣'), 3n);
check('mixed scripts', pyInt('١3'), 13n);
check('astral digits', pyInt('𝟑'), 3n);
check('big integer', pyInt('99999999999999999999'), 99999999999999999999n);
for (const bad of ['', ' ', '_1', '1_', '1__0', '0x2', '1.5', '²', 'abc', '+', '-']) {
  throws(`int(${pyRepr(bad)})`, () => pyInt(bad), PyValueError);
}

// --- str / repr ----------------------------------------------------------
check('str true', pyStr(true), 'True');
check('str false', pyStr(false), 'False');
check('repr plain', pyRepr('ab'), "'ab'");
check('repr single quote', pyRepr("a'b"), '"a\'b"');
check('repr both quotes', pyRepr('a\'b"c'), '\'a\\\'b"c\'');
check('repr newline', pyRepr('a\nb'), "'a\\nb'");
check('repr zero width', pyRepr('​'), "'\\u200b'");
check('repr astral control', pyRepr('\u{1d173}'), "'\\U0001d173'");
check('repr printable unicode', pyRepr('é中'), "'é中'");

console.log(failures === 0 ? 'all library self-tests pass' : `${failures} self-test failure(s)`);
if (failures > 0) process.exitCode = 1;

